<?php $pageTitle='Participants';require_once dirname(__DIR__).'/includes/header.php';require_once dirname(__DIR__).'/includes/auth.php';require_auth(['super_admin','admin']);$t=active_tournament($pdo);$tid=(int)($t['id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){try{verify_csrf($_POST['csrf_token']??null);$action=$_POST['action']??'save';if($action==='delete'){$id=(int)$_POST['id'];$pdo->prepare('DELETE FROM participants WHERE id=? AND tournament_id=?')->execute([$id,$tid]);audit_log($pdo,'delete','participant',$id,'Deleted participant');}elseif($action==='import'){$file=$_FILES['csv']??[];if(($file['error']??1)!==UPLOAD_ERR_OK)throw new RuntimeException('Choose a valid CSV file.');$h=fopen($file['tmp_name'],'r');$count=0;while(($row=fgetcsv($h))!==false){if($count===0&&strtolower($row[0]??'')==='name'){$count++;continue;}if(empty($row[0]))continue;$pdo->prepare('INSERT INTO participants (tournament_id,name,team_name,institution,seed,status) VALUES (?,?,?,?,?,"active")')->execute([$tid,trim($row[0]),trim($row[1]??$row[0]),trim($row[2]??''),($row[3]??'')!==''?(int)$row[3]:null]);$count++;}fclose($h);audit_log($pdo,'import','participant',null,'Imported participant CSV');}else{$id=(int)($_POST['id']??0);$name=trim($_POST['name']??'');if($name==='')throw new RuntimeException('Participant name is required.');$logo=handle_logo_upload($_FILES['logo']??[]);if($id){$sql='UPDATE participants SET name=?,team_name=?,institution=?,seed=?,status=?'.($logo?',logo=?':'').' WHERE id=? AND tournament_id=?';$params=[$name,trim($_POST['team_name']??''),trim($_POST['institution']??''),$_POST['seed']!==''?(int)$_POST['seed']:null,$_POST['status']];if($logo)$params[]=$logo;$params[]=$id;$params[]=$tid;$pdo->prepare($sql)->execute($params);audit_log($pdo,'update','participant',$id,'Updated '.$name);}else{$pdo->prepare('INSERT INTO participants (tournament_id,name,team_name,institution,logo,seed,status) VALUES (?,?,?,?,?,?,?)')->execute([$tid,$name,trim($_POST['team_name']??''),trim($_POST['institution']??''),$logo,$_POST['seed']!==''?(int)$_POST['seed']:null,$_POST['status']]);audit_log($pdo,'create','participant',(int)$pdo->lastInsertId(),'Created '.$name);}}header('Location: participants.php?saved=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$x=$pdo->prepare('SELECT * FROM participants WHERE id=? AND tournament_id=?');$x->execute([(int)$_GET['edit'],$tid]);$edit=$x->fetch();}$q=trim($_GET['q']??'');$s=$pdo->prepare('SELECT * FROM participants WHERE tournament_id=? AND name LIKE ? ORDER BY seed IS NULL,seed,name');$s->execute([$tid,'%'.$q.'%']);require dirname(__DIR__).'/includes/sidebar.php';?>
<div class="grid grid-3"><section class="card"><div class="section-head"><div><div class="eyebrow">Roster</div><h2><?=$edit?'Edit':'Add'?> participant</h2></div></div><?php if(!empty($error)):?><p style="color:#fca5a5"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data" class="grid"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$edit['id']??''?>"><div><label>Participant Name</label><input name="name" required value="<?=e($edit['name']??'')?>"></div><div><label>Team Name</label><input name="team_name" value="<?=e($edit['team_name']??'')?>"></div><div><label>Institution</label><input name="institution" value="<?=e($edit['institution']??'')?>"></div><div><label>Seed</label><input type="number" min="1" name="seed" value="<?=e((string)($edit['seed']??''))?>"></div><div><label>Logo (JPG, PNG, WebP · max 2 MB)</label><input type="file" name="logo" accept=".jpg,.jpeg,.png,.webp"></div><div><label>Status</label><select name="status"><?php foreach(['active','inactive','disqualified'] as $st):?><option <?=$st===($edit['status']??'active')?'selected':''?>><?=$st?></option><?php endforeach;?></select></div><button class="btn btn-primary" type="submit">Save Participant</button></form><hr style="border-color:var(--border);margin:28px 0"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="import"><label>Import CSV (name, team, institution, seed)</label><input type="file" name="csv" accept=".csv" required><button class="btn btn-ghost" style="margin-top:10px" type="submit">Import Participants</button></form></section><section style="grid-column:span 2"><div class="toolbar"><form class="search"><i class="fa-solid fa-search"></i><input name="q" placeholder="Search participant" value="<?=e($q)?>"></form><span class="badge"><?=$s->rowCount()?> registered</span></div><div class="table-wrap"><table><thead><tr><th>Seed</th><th>Participant</th><th>Institution</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($s->fetchAll() as $p):?><tr><td>#<?=e((string)($p['seed']??'-'))?></td><td><strong><?=e($p['name'])?></strong><small style="display:block"><?=e($p['team_name'])?></small></td><td><?=e($p['institution'])?></td><td><span class="badge"><?=e($p['status'])?></span></td><td><div class="inline-actions"><a class="btn btn-sm" href="?edit=<?=$p['id']?>">Edit</a><form method="post" onsubmit="return confirm('Delete this participant?')"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-sm btn-danger">Delete</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section></div>
